B.asD=new A.bU("Heavy bleeding","\u0ec0\u0ea5\u0eb7\u0ead\u0e94\u0ead\u0ead\u0e81\u0eab\u0ebc\u0eb2\u0e8d")
B.asy=new A.bU("Press hard on the wound","\u0e81\u0ebb\u0e94\u0e9a\u0eb2\u0e94\u0ec1\u0e9c\u0ec3\u0eab\u0ec9\u0ec1\u0eae\u0e87")
B.asU=new A.bU("Press firmly on the wound with your hands. If you can, put a cloth or plastic bag between your hand and the blood. If the person can press on it themselves, let them.","\u0e81\u0ebb\u0e94\u0e9a\u0eb2\u0e94\u0ec1\u0e9c\u0ec3\u0eab\u0ec9\u0ec1\u0edc\u0ec9\u0e99\u0e94\u0ec9\u0ea7\u0e8d\u0ea1\u0eb7. \u0e96\u0ec9\u0eb2\u0ec0\u0e9b\u0eb1\u0e99\u0ec4\u0e9b\u0ec4\u0e94\u0ec9 \u0ec3\u0eab\u0ec9\u0ec3\u0e8a\u0ec9\u0e9c\u0ec9\u0eb2 \u0eab\u0ebc\u0eb7 \u0e96\u0ebb\u0e87\u0ea2\u0eb2\u0e87 \u0e81\u0eb1\u0ec9\u0e99\u0ea5\u0eb0\u0eab\u0ea7\u0ec8\u0eb2\u0e87\u0ea1\u0eb7\u0e82\u0ead\u0e87\u0e97\u0ec8\u0eb2\u0e99\u0e81\u0eb1\u0e9a\u0ec0\u0ea5\u0eb7\u0ead\u0e94. \u0e96\u0ec9\u0eb2\u0e9c\u0eb9\u0ec9\u0e9a\u0eb2\u0e94\u0ec0\u0e88\u0eb1\u0e9a\u0e81\u0ebb\u0e94\u0ec0\u0ead\u0e87\u0ec4\u0e94\u0ec9 \u0ec3\u0eab\u0ec9\u0ec0\u0e82\u0ebb\u0eb2\u0e81\u0ebb\u0e94\u0ec0\u0ead\u0e87.")
B.asC=new A.bU("Help the person lie down.","\u0e8a\u0ec8\u0ea7\u0e8d\u0ec3\u0eab\u0ec9\u0e9c\u0eb9\u0ec9\u0e9a\u0eb2\u0e94\u0ec0\u0e88\u0eb1\u0e9a\u0e99\u0ead\u0e99\u0ea5\u0ebb\u0e87.")
B.ast=new A.bU("Keep pressing. If blood soaks through, put another cloth on top and press harder. Don't take the first cloth off.","\u0e81\u0ebb\u0e94\u0ec4\u0ea7\u0ec9\u0e95\u0ecd\u0ec8\u0ec4\u0e9b. \u0e96\u0ec9\u0eb2\u0ec0\u0ea5\u0eb7\u0ead\u0e94\u0e8a\u0eb6\u0ea1\u0ead\u0ead\u0e81\u0ea1\u0eb2 \u0ec3\u0eab\u0ec9\u0ea7\u0eb2\u0e87\u0e9c\u0ec9\u0eb2\u0ead\u0eb5\u0e81\u0e9c\u0eb7\u0e99\u0edc\u0eb6\u0ec8\u0e87\u0e97\u0eb1\u0e9a\u0ec3\u0eaa\u0ec8 \u0ec1\u0ea5\u0ec9\u0ea7\u0e81\u0ebb\u0e94\u0ec3\u0eab\u0ec9\u0ec1\u0eae\u0e87\u0e82\u0eb6\u0ec9\u0e99. \u0ea2\u0ec8\u0eb2\u0ec0\u0ead\u0ebb\u0eb2\u0e9c\u0ec9\u0eb2\u0e9c\u0eb7\u0e99\u0e97\u0eb3\u0ead\u0eb4\u0e94\u0ead\u0ead\u0e81.")
B.asF=new A.bU("Keep them lying on their back and keep them warm.","\u0ec3\u0eab\u0ec9\u0e9c\u0eb9\u0ec9\u0e9a\u0eb2\u0e94\u0ec0\u0e88\u0eb1\u0e9a\u0e99\u0ead\u0e99\u0eab\u0e87\u0eb2\u0e8d \u0ec1\u0ea5\u0eb0 \u0eae\u0eb1\u0e81\u0eaa\u0eb2\u0ec3\u0eab\u0ec9\u0ead\u0ebb\u0e9a\u0ead\u0eb8\u0ec8\u0e99.")
B.a5H=s([B.asU,B.asC,B.ast,B.asF],t.Pr)
B.ass=new A.bU("If something is stuck in the wound, such as a knife, don't pull it out. Press around it.","\u0e96\u0ec9\u0eb2\u0ea1\u0eb5\u0ea7\u0eb1\u0e94\u0e96\u0eb8\u0e9b\u0eb1\u0e81\u0ea2\u0eb9\u0ec8\u0ec3\u0e99\u0e9a\u0eb2\u0e94\u0ec1\u0e9c \u0ec0\u0e8a\u0eb1\u0ec8\u0e99: \u0ea1\u0eb5\u0e94, \u0ea2\u0ec8\u0eb2\u0e94\u0eb6\u0e87\u0ead\u0ead\u0e81. \u0ec3\u0eab\u0ec9\u0e81\u0ebb\u0e94\u0ead\u0ec9\u0ead\u0ea1\u0eae\u0ead\u0e9a\u0ea1\u0eb1\u0e99.")
B.asn=new A.bU("If pressing doesn't stop bleeding from an arm or leg and you have a tourniquet, use it. Leave it on until the crew arrives.","\u0e96\u0ec9\u0eb2\u0e81\u0ebb\u0e94\u0ec1\u0ea5\u0ec9\u0ea7 \u0ec0\u0ea5\u0eb7\u0ead\u0e94\u0ea2\u0eb9\u0ec8\u0ec1\u0e82\u0e99 \u0eab\u0ebc\u0eb7 \u0e82\u0eb2\u0e8d\u0eb1\u0e87\u0e9a\u0ecd\u0ec8\u0ea2\u0eb8\u0e94 \u0ec1\u0ea5\u0eb0 \u0e97\u0ec8\u0eb2\u0e99\u0ea1\u0eb5\u0eaa\u0eb2\u0e8d\u0eae\u0eb1\u0e94\u0eab\u0ec9\u0eb2\u0ea1\u0ec0\u0ea5\u0eb7\u0ead\u0e94 \u0ec3\u0eab\u0ec9\u0ec3\u0e8a\u0ec9\u0ea1\u0eb1\u0e99. \u0eae\u0eb1\u0e94\u0ec4\u0ea7\u0ec9\u0e88\u0ebb\u0e99\u0e81\u0ea7\u0ec8\u0eb2\u0e97\u0eb5\u0ea1\u0e81\u0eb9\u0ec9\u0ec4\u0e9e\u0e88\u0eb0\u0ea1\u0eb2\u0eae\u0ead\u0e94.")
B.asw=new A.bU('If the person stops responding, go to "Unconscious person".','\u0e96\u0ec9\u0eb2\u0e9c\u0eb9\u0ec9\u0e9a\u0eb2\u0e94\u0ec0\u0e88\u0eb1\u0e9a\u0e9a\u0ecd\u0ec8\u0e95\u0ead\u0e9a\u0eaa\u0eb0\u0edc\u0ead\u0e87 \u0ec3\u0eab\u0ec9\u0ec4\u0e9b\u0e97\u0eb5\u0ec8 "\u0e84\u0ebb\u0e99\u0eaa\u0eb0\u0eab\u0ebc\u0ebb\u0e9a".')
B.a5L=s([B.ass,B.asn,B.asw],t.Pr)
