B.a4k=new A.cH(57554,"Lucide","lucide_icons_flutter",!1)
B.asN=new A.bU("Burns","\u0ec4\u0e9f\u0ea5\u0ea7\u0e81")
B.asL=new A.bU("Cool with running water","\u0ea5\u0ec9\u0eb2\u0e87\u0e94\u0ec9\u0ea7\u0e8d\u0e99\u0ec9\u0eb3\u0ec4\u0eab\u0ebc\u0ec3\u0eab\u0ec9\u0ec0\u0ea2\u0eb1\u0e99")
B.asS=new A.bU("Cool the burn under clean running water for at least 10 minutes, ideally 20.","\u0ea5\u0ec9\u0eb2\u0e87\u0e9a\u0ec8\u0ead\u0e99\u0e97\u0eb5\u0ec8\u0e96\u0eb7\u0e81\u0ea5\u0ea7\u0e81\u0e94\u0ec9\u0ea7\u0e8d\u0e99\u0ec9\u0eb3\u0eaa\u0eb0\u0ead\u0eb2\u0e94\u0e97\u0eb5\u0ec8\u0ec4\u0eab\u0ebc \u0ea2\u0ec8\u0eb2\u0e87\u0edc\u0ec9\u0ead\u0e8d 10 \u0e99\u0eb2\u0e97\u0eb5, \u0e94\u0eb5\u0e97\u0eb5\u0ec8\u0eaa\u0eb8\u0e94\u0ec1\u0ea1\u0ec8\u0e99 20 \u0e99\u0eb2\u0e97\u0eb5.")
B.asP=new A.bU("No running water? Pour any cool drink over it, such as juice or milk.","\u0e96\u0ec9\u0eb2\u0e9a\u0ecd\u0ec8\u0ea1\u0eb5\u0e99\u0ec9\u0eb3\u0ec4\u0eab\u0ebc \u0ec3\u0eab\u0ec9\u0e96\u0ead\u0e81\u0ec0\u0e84\u0eb7\u0ec8\u0ead\u0e87\u0e94\u0eb7\u0ec8\u0ea1\u0ec0\u0ea2\u0eb1\u0e99\u0ec3\u0e94\u0e81\u0ecd\u0ec4\u0e94\u0ec9\u0ec3\u0eaa\u0ec8 \u0ec0\u0e8a\u0eb1\u0ec8\u0e99: \u0e99\u0ec9\u0eb3\u0edd\u0eb2\u0e81\u0ec4\u0ea1\u0ec9 \u0eab\u0ebc\u0eb7 \u0e99\u0ebb\u0ea1.")
